-- Clear 1,174 unusable waypoint rows belonging to 51 absent creature GUIDs.
-- Clear only 26 missing script references on GUIDs 79796, 86596 and 90445.
-- Preserve all 160 live waypoint coordinates, orientations, wait times and comments.
-- Preserve valid Janey Anship scripts 141301/141302 and every script definition.
-- Missing references were checked against the current DB, the older DB and official ClassicDB data.
SET NAMES utf8;
DELETE FROM creature_movement WHERE Id IN(16480,16552,21040,21053,21100,21103,21660,21661,21698,38993,43588,50421,50422,53109,53110,79689,89854,90334,90358,134221,1007529,7000032,7000077,7000109,7000111,7000116,9000024,9000025,9000026,9000027,9000031,9000050,9000058,9000166,9000168,9000169,9000172,9000176,9000182,9000183,9000184,9000185,9000192,9000207,9000210,9000216,9000217,9000253,9000395,9000396,9000398) AND NOT EXISTS(SELECT 1 FROM creature WHERE creature.guid=creature_movement.Id);
SELECT ROW_COUNT();
UPDATE creature_movement SET ScriptId=0 WHERE (Id,Point,ScriptId) IN((79796,7,352001),(79796,10,352002),(79796,13,352003),(79796,16,352004),(79796,22,352005),(79796,27,352006),(86596,11,141304),(86596,25,141306),(86596,46,141307),(86596,55,141305),(86596,59,141303),(90445,2,362701),(90445,4,362702),(90445,7,362703),(90445,12,362704),(90445,17,362705),(90445,21,362706),(90445,26,362707),(90445,30,362708),(90445,35,362709),(90445,39,362710),(90445,43,362711),(90445,47,362712),(90445,52,362713),(90445,57,362714),(90445,61,362715));
